{%- set v_landmarkLabel = (p.landmarkLabel ?? null) -%}
{%- set c_4 -%}
  {%- set c_3 -%}
    {%- set c_2 -%}
      {{ include('blocks/hero-head.html.twig', {'p': {'brand': ui_get(v_nav, ['brand']), 'links': ui_get(v_nav, ['links']), 'current': ui_get(v_nav, ['current']), 'login': ui_get(v_nav, ['login']), 'loginHref': ui_get(v_nav, ['loginHref']), 'skip': ui_get(v_nav, ['skip']), 'navLabel': ui_get(v_nav, ['label']), 'cta': ui_get(v_actions, ['cta']), 'href': ui_get(v_actions, ['href']), 'landmarkLabel': v_landmarkLabel}}, with_context = false) }}
