          {{ include('blocks/hero-badge.html.twig', {'p': {'label': v_badge, 'mark': v_badgeMark}}, with_context = false) }}
        {%- endif %}
        {{ include('blocks/weighted-title.html.twig', {'p': {'id': 'home-hero-title', 'title': v_title, 'weights': ui_preset('blocks/presets/defaults.json', ['hero', 'titleWeights']), 'level': v_level}}, with_context = false) }}
        {%- if ui_t(ui_eq(ui_get(v_actions, ['mode']), 'form')) %}
          {{ include('blocks/prompt-composer.html.twig', {'p': {'label': ui_get(v_actions, ['emailLabel']), 'attachLabel': ui_get(v_composer, ['attachLabel']), 'modelLabel': ui_get(v_composer, ['modelLabel']), 'send': ui_get(v_actions, ['cta']), 'href': ui_get(v_actions, ['href'])}}, with_context = false) }}
        {%- elseif ui_t(ui_get(v_actions, ['cta'])) %}
          {{ include('blocks/action-group.html.twig', {'p': {'primary': ui_get(v_actions, ['cta']), 'primaryHref': ui_get(v_actions, ['href']), 'secondary': (ui_t(ui_eq(ui_get(v_actions, ['mode']), 'two')) ? ui_get(v_actions, ['secondary']) : null), 'secondaryHref': ui_get(v_actions, ['secondaryHref']), 'align': (ui_t(true) ? 'center' : 'start')}}, with_context = false) }}
        {%- endif %}
        {%- if ui_t(v_topics) %}
          {{ include('blocks/topic-chips.html.twig', {'p': {'topics': v_topics, 'tone': 'inverse'}}, with_context = false) }}
        {%- endif %}
      {%- endset -%}
      {{ include('ui/stack/stack.html.twig', {'p': {'Gap': '0', 'Align': 'center', 'Class': ui_s(ui_cnv(['mx-auto w-full pt-24 pb-16', ui_preset('blocks/presets/defaults.json', ['hero', 'column'])])), 'Attrs': ui_attrs(['data-testid', 'hero-column'])}, 'children': c_1}, with_context = false) }}
    {%- endset -%}
