  {{ include('ui/container/container.html.twig', {'p': {'Class': ui_s(ui_cnv(['mx-auto w-full px-8', ui_preset('blocks/presets/defaults.json', ['hero', 'container'])])), 'Attrs': ui_attrs(['data-slot', 'container'])}, 'children': c_3}, with_context = false) }}
{%- endset -%}
{{ include('ui/block/block.html.twig', {'p': {'Tag': 'section', 'Class': ui_s(ui_cnv(['flex w-full flex-col bg-foreground text-background py-8 [&_.text-muted-foreground]:text-background/70', ui_preset('blocks/presets/defaults.json', ['hero', 'band'])])), 'Attrs': ui_attrs(['aria-labelledby', (ui_t(v_landmarkLabel) ? null : 'home-hero-title'), 'data-testid', 'section', 'data-tone', 'inverse', 'data-density', v_density, 'data-chrome', 'nav', 'aria-label', v_landmarkLabel])}, 'children': c_4}, with_context = false) }}
